import { Component, computed, input, output } from '@angular/core';
import { NzTagModule } from 'ng-zorro-antd/tag';

/** Bộ hue có sẵn của design system (bg/border/text đều bám Light/Dark, text AAA). */
export const HRM_TAG_HUES = ['gray', 'blue', 'cyan', 'green', 'yellow', 'orange', 'red', 'pink', 'purple', 'teal'] as const;
export type HrmTagHue = (typeof HRM_TAG_HUES)[number];
/** color nhận: 1 hue DS, preset trạng thái nz, hoặc mã hex tuỳ ý. */
export type HrmTagColor = HrmTagHue | 'success' | 'processing' | 'warning' | 'error' | 'default' | (string & {});
/** 4 kiểu nền: filled đặc · light nền nhạt (mặc định) · lighter rất nhạt · stroke viền. */
export type HrmTagVariant = 'filled' | 'light' | 'lighter' | 'stroke';

const HUE_SET = new Set<string>(HRM_TAG_HUES);

/** hrm-tag — bọc nz-tag. Nhãn/chip phân loại + trạng thái.
 *  - color = 1 hue DS ('purple'|'teal'|…) → dùng bảng màu tag tokens (khuyến nghị, có legend).
 *  - color = preset nz ('success'|'warning'|'error'|'processing') hoặc mã hex → truyền thẳng.
 *  - variant (chỉ áp cho hue DS): filled/light/lighter/stroke.
 *  - dot: chấm màu dẫn đầu (trạng thái). size: 'sm' (20px) | 'md' (24px).
 *  Hue DS đặt [data-hue]+[data-variant] trên host, nzColor về 'default' để bridge override. */
@Component({
  selector: 'hrm-tag',
  imports: [NzTagModule],
  template: `
    <nz-tag
      [nzColor]="nzColor()"
      [nzMode]="closeable() ? 'closeable' : 'default'"
      (nzOnClose)="closed.emit()">
      @if (dot()) { <span class="hrm-tag-dot"></span> }
      <ng-content />
    </nz-tag>
  `,
  host: {
    class: 'hrm-tag',
    '[attr.data-hue]': 'hue()',
    '[attr.data-variant]': 'hue() ? variant() : null',
    '[attr.data-size]': 'size()',
  },
})
export class HrmTag {
  readonly color = input<HrmTagColor>('default');
  readonly variant = input<HrmTagVariant>('light');
  readonly size = input<'sm' | 'md'>('md');
  readonly dot = input(false);
  readonly closeable = input(false);
  readonly closed = output<void>();

  /** hue DS → tên hue (gắn [data-hue]); ngược lại null (không gắn). */
  protected readonly hue = computed(() => (HUE_SET.has(this.color()) ? this.color() : null));
  /** hue DS → 'default' (để bridge tô); còn lại truyền nzColor gốc (preset/hex). */
  protected readonly nzColor = computed(() => (HUE_SET.has(this.color()) ? 'default' : this.color()));
}
